import os
from langchain_core.callbacks import BaseCallbackHandler
from langchain.agents import create_tool_calling_agent, AgentExecutor
from langchain_openai import ChatOpenAI
from langchain_core.tools import tool
from langchain_core.prompts import ChatPromptTemplate

class TraceCallback(BaseCallbackHandler):
    def on_llm_start(self, serialized, prompts, **kwargs):
        print(f'[LLM开始] {serialized.get("name", "")}')
    def on_tool_start(self, serialized, input_str, **kwargs):
        print(f'[工具开始] {serialized.get("name", "")}: {input_str}')
    def on_tool_end(self, output, **kwargs):
        print(f'[工具结束] {output}')

@tool
def calculate(expr: str) -> str:
    """计算表达式"""
    return str(eval(expr))

llm = ChatOpenAI(model=os.environ.get("MODEL_NAME", "deepseek-v4-pro"), base_url=os.environ.get("OPENAI_BASE_URL", "https://api.deepseek.com"), api_key=os.environ.get("OPENAI_API_KEY", ""))
prompt = ChatPromptTemplate.from_messages([('system','你是助手'), ('human','{input}'), ('placeholder','{agent_scratchpad}')])
agent = create_tool_calling_agent(llm, [calculate], prompt)
# 注入 callback
executor = AgentExecutor(agent=agent, tools=[calculate], callbacks=[TraceCallback()])
print(executor.invoke({'input': '计算 2+3'})['output'])

